------------ define ------------
--下拉暂时还没做
local node1 = "ToggleCellNode1"--可下拉父节点
local node2 = "ToggleCellNode2"--可下拉子节点
local nodeBehaviourPath = "Game.Behaviours.CommonTabToggleLeftCell"
------------ define ------------


---@class CommonTabToggleLeft
---@field ListView                      	SuperScrollView.LoopGridView
local CommonTabToggleLeft = Class("CommonTabToggleLeft")

function CommonTabToggleLeft:__init()
    self.togglesData = {}
    self.selectIndex = -1
    self.expandRange = {}--从父节点开始
    self.customFreshFunction = nil
end

function CommonTabToggleLeft:__delete()
    self.controller = nil
    self.togglesData = nil
    self.selectIndex = nil
    self.expandRange = nil
    self.customFreshFunction = nil
end

function CommonTabToggleLeft:Awake()

end

---绘制左侧可点页签
--- togglesData 格式参考
