---@param togglesData table[] @ 数据列表
---@param openType integer @ 初始选中的索引
---@param cb fun():void | nil @ 自定义单元刷新回调
---@param isInstant boolean @ 是否立即执行初始选中回调（默认 false）
function CommonTabToggleLeft:FillToggles(togglesData, openType, cb, isInstant)
    if not isNull(openType) then
        self.selectIndex = openType - 1
    else
        self.selectIndex = 0--不穿的话默认打开第一个
    end
    self.togglesData = togglesData
    self.isInstant_ = isInstant
    if not self.ListView.IsListViewInit then
        self.ListView:InitGridView(#togglesData, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ListView, #togglesData)
    end
    if cb then
        self.customFreshFunction = cb
    end
end

function CommonTabToggleLeft:FreshListView()
    self.ListView:RefreshAllShownItem()
end

--- 滚动至指定索引位置（一定确保在 FillToggles 之后执行）
function CommonTabToggleLeft:MoeToItemByIndex(luaIndex)
    self.ListView:MovePanelToItemByIndex(luaIndex - 1, 0, 0)
end

---SetAfterAction
---按钮点击后的事件回调
---@param cb function
function CommonTabToggleLeft:SetAfterAction(cb)
    self.cb = cb
end

---左侧每一个toggle
function CommonTabToggleLeft:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem(node1)
    local node = GetLuaBehaviour(cell.gameObject, nodeBehaviourPath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        node:Init()
    end
    if not KTool.IsNull(node) then
        --node.Env:FreshBaseUI({
        --    text = self.togglesData[index + 1].text,
        --    --textColor = self.togglesData[index + 1].textColor,--颜色参数可不传
        --    selectImgPath = self.togglesData[index + 1].selectImgPath,--选中时显示的图片路径，可不传
        --    lock = self.togglesData[index + 1].lock,--常驻显示的图片，如养成中的锁定状态
        --})

        ---@type CommonTabToggleLeftCell
        local nodeEnv =     node.Env
        nodeEnv:FreshBaseUI(self.togglesData[index + 1])
        --小红点
        nodeEnv:FreshRedPointStatus(false)
        if not isNull(self.togglesData[index + 1].redPointStrNode) then
            GameUtils.BindRedPoint(self.togglesData[index + 1].redPointStrNode, nodeEnv:GetRedPoint().parent, true)
        elseif not isNull(self.togglesData[index + 1].redPointStatus) then     --新增一个外部强行控制小红点的变量
            nodeEnv:FreshRedPointStatus(checkBool(self.togglesData[index + 1].redPointStatus))
        end
        --
        local isSelected = index == self.selectIndex
        nodeEnv:FreshSelectStatus(isSelected, self.togglesData[index + 1])
        if self.customFreshFunction ~= nil then
            self.customFreshFunction(isSelected, index + 1, self.selectIndex, self.togglesData[index + 1], nodeEnv)
        end
        nodeEnv:SetCallBack(function() --点击回调
            if index ~= self.selectIndex then --屏蔽掉重复点击当前选择的toggle
                local funcResult = self.togglesData[index + 1].func(self.togglesData[index + 1], index + 1)
                if funcResult == 0 then --选中失败时返回0，不切换选中状态
                    return--选中失败，直接返回
                end
                if table.count(self.expandRange) <= 0 then --子节点没展开
                    if self.togglesData[index + 1].child then--有子节点
                        local child = clone(self.togglesData[index + 1].child)
                        self.expandRange[1] = index
                        self.expandRange[2] = index + table.count(child)
                        for i = table.count(child), 1, -1 do
                            table.insert(self.togglesData, index + 1+1, child[i])
                        end
                        self.selectIndex = index + 1--默认选中第一个子节点
                        self.togglesData[self.selectIndex].func()--父节点的方法调一遍
                        self.togglesData[self.selectIndex + 1].func()--第一个子节点的方法调一遍
                        GameUtils.ReloadData(self.ListView, #self.togglesData)
                        return
                    end
                else--子节点展开了
                    if index >= self.expandRange[1] and index <= self.expandRange[2] then--选择的是展开列表中的节点
                        if index == self.expandRange[1] then--选的是父节点
                            return
                        else

                        end
                    else--移除数据
                        local childCount = self.expandRange[2] - self.expandRange[1]
                        for i = childCount, 1, -1 do
                            table.remove(self.togglesData, self.expandRange[1] + 1 + 1)
                        end
                        self.selectIndex = index > self.expandRange[1] and index - childCount or index
                        self.expandRange = {}
                        self.togglesData[self.selectIndex + 1].func()
                        GameUtils.ReloadData(self.ListView, #self.togglesData)
                        return
                    end
                end


                --成功选中后才会切换选中状态
                nodeEnv:FreshSelectStatus(true, self.togglesData[index + 1])
                local preNodeGo = self.ListView:GetShownItemByItemIndex(self.selectIndex)
                if preNodeGo then
                    local preNode = GetLuaBehaviour(preNodeGo.gameObject, nodeBehaviourPath)
                    preNode.Env:FreshSelectStatus(false, self.togglesData[index + 1])
                end
                self.selectIndex = index
                if self.cb then
                    self.cb(self.selectIndex)
                end
            end
        end)
        -- 设置数据后，选中的首次是否立即执行回调
        if isSelected and self.isInstant_ then
            self.togglesData[index + 1].func(self.togglesData[index + 1], index + 1)
            self.isInstant_ = nil
        end
    end
    return cell
end

--用来获取节点go
function CommonTabToggleLeft:GetTogGoByIndex(ind)
    return self.ListView:GetShownItemByItemIndex(ind)
end

function CommonTabToggleLeft:GetTogGoEnvByIndex(index)
    local cell = self:GetTogGoByIndex(index)
    if not isNull(cell) then
        local env = CfUtils.GetLuaScr(cell,nodeBehaviourPath)
        return env
    end
    return nil
end

function CommonTabToggleLeft:FreshTabRedPointByIndex(index,status)
    local cell = self:GetTogGoByIndex(index)
    if not isNull(cell) then
        local env = CfUtils.GetLuaScr(cell,nodeBehaviourPath)
        env:FreshRedPointStatus(status)
    end
end

function CommonTabToggleLeft:OnDestroy()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        for k, v in pairs(self.togglesData) do
            if not isNull(v.redPointStrNode) then
                GameUtils.RemoveRedPointCallBack(v.redPointStrNode)
            end
        end
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return CommonTabToggleLeft